"use strict";

// Sends each webhook in order, spacing the requests delayMs apart.
// Returns a function that cancels any webhooks not yet sent.
function scheduleWebhooks(urls, delayMs, send) {
  if (!Array.isArray(urls)) throw new TypeError("urls must be an array");
  if (!Number.isFinite(delayMs) || delayMs < 0) throw new RangeError("delayMs must be a non-negative number");
  const timers = [];
  for (var i = 0; i < urls.length; i++) {
    timers.push(setTimeout(() => send(urls[i]), i * delayMs));
  }
  return function cancel() {
    for (const timer of timers) clearTimeout(timer);
  };
}

module.exports = { scheduleWebhooks };

