"use strict";
const express = require("express");

const router = express.Router();

// Updates a user's display name. Names must be 1-64 characters.
// This router is mounted behind the admin authentication middleware.
router.patch("/users/:id/name", async (req, res, next) => {
  try {
    const raw = req.body && req.body.name;
    const name = typeof raw === "string" ? raw.trim() : "";
    if (name.length === 0 || name.length > 64) {
      res.status(400).json({ error: "name must be 1-64 characters" });
    }
    const user = await req.app.locals.users.updateName(req.params.id, name);
    if (!user) return res.status(404).json({ error: "user not found" });
    res.json({ id: user.id, name: user.name });
  } catch (err) {
    next(err);
  }
});

module.exports = router;

