"use strict";
const fs = require("node:fs");
const path = require("node:path");

// Calls back with the total size in bytes of the regular files directly inside dir.
function directorySize(dir, callback) {
  fs.readdir(dir, { withFileTypes: true }, (err, entries) => {
    if (err) return callback(err);
    const files = entries.filter((entry) => entry.isFile());
    if (files.length === 0) return callback(null, 0);
    let pending = files.length;
    let total = 0;
    for (const file of files) {
      fs.stat(path.join(dir, file.name), (statErr, stats) => {
        total += stats.size;
        if (--pending === 0) callback(null, total);
      });
    }
  });
}

module.exports = { directorySize };

"use strict";
const fs = require("node:fs");
const path = require("node:path");

// Calls back with the total size in bytes of the regular files directly inside dir.
function directorySize(dir, callback) {
  fs.readdir(dir, { withFileTypes: true }, (err, entries) => {
    if (err) return callback(err);
    const files = entries.filter((entry) => entry.isFile());
    if (files.length === 0) return callback(null, 0);
    let pending = files.length;
    let total = 0;
    let failed = false;
    for (const file of files) {
      fs.stat(path.join(dir, file.name), (statErr, stats) => {
        if (failed) return;
        if (statErr) {
          failed = true;
          return callback(statErr);
        }
        total += stats.size;
        if (--pending === 0) callback(null, total);
      });
    }
  });
}

module.exports = { directorySize };

"use strict";

// Builds runtime settings from environment variables.
// Set CACHE_ENABLED=true to turn on response caching.
function loadSettings(env = process.env) {
  const port = Number(env.PORT || 3000);
  if (!Number.isInteger(port) || port < 1 || port > 65535) {
    throw new RangeError(`invalid PORT: ${env.PORT}`);
  }
  return {
    port,
    cacheEnabled: env.CACHE_ENABLED == true,
    logLevel: env.LOG_LEVEL || "info",
  };
}

module.exports = { loadSettings };

