"use strict";

const DEFAULTS = { currency: "EUR", locale: "en-US", currencyDisplay: "symbol" };

// Returns a price formatter; options override the defaults for this formatter only.
function createPriceFormatter(options = {}) {
  const config = Object.assign(DEFAULTS, options);
  const format = new Intl.NumberFormat(config.locale, {
    style: "currency",
    currency: config.currency,
    currencyDisplay: config.currencyDisplay,
  });
  return (amount) => {
    if (typeof amount !== "number" || !Number.isFinite(amount)) {
      throw new TypeError("amount must be a finite number");
    }
    return format.format(amount);
  };
}

module.exports = { createPriceFormatter };

