"use strict";
const express = require("express");
const { EventEmitter } = require("node:events");

const notifications = new EventEmitter();
notifications.setMaxListeners(0);
const router = express.Router();

// Streams notifications to the client as server-sent events until it disconnects.
router.get("/notifications/stream", (req, res) => {
  res.set({ "Content-Type": "text/event-stream", "Cache-Control": "no-cache" });
  res.flushHeaders();

  const send = (event) => {
    res.write(`data: ${JSON.stringify(event)}\n\n`);
  };
  notifications.on("notification", send);
});

// Publishes a public announcement to every connected client.
function publish(event) {
  notifications.emit("notification", event);
}

module.exports = { router, publish };

"use strict";
const express = require("express");
const { EventEmitter } = require("node:events");

const notifications = new EventEmitter();
notifications.setMaxListeners(0);
const router = express.Router();

// Streams notifications to the client as server-sent events until it disconnects.
router.get("/notifications/stream", (req, res) => {
  res.set({ "Content-Type": "text/event-stream", "Cache-Control": "no-cache" });
  res.flushHeaders();

  const send = (event) => {
    res.write(`data: ${JSON.stringify(event)}\n\n`);
  };
  notifications.on("notification", send);
  req.on("close", () => notifications.off("notification", send));
});

// Publishes a public announcement to every connected client.
function publish(event) {
  notifications.emit("notification", event);
}

module.exports = { router, publish };

"use strict";

function isPlainObject(value) {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

// Recursively merges source into target and returns target.
// Used to apply user preference patches from the request body to stored preferences.
function deepMerge(target, source) {
  for (const key of Object.keys(source)) {
    if (isPlainObject(source[key])) {
      if (!isPlainObject(target[key])) target[key] = {};
      deepMerge(target[key], source[key]);
    } else {
      target[key] = source[key];
    }
  }
  return target;
}

module.exports = { deepMerge };

"use strict";

const FORBIDDEN_KEYS = new Set(["__proto__", "constructor", "prototype"]);

function isPlainObject(value) {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

// Recursively merges source into target and returns target.
// Used to apply user preference patches from the request body to stored preferences.
function deepMerge(target, source) {
  for (const key of Object.keys(source)) {
    if (FORBIDDEN_KEYS.has(key)) continue;
    if (isPlainObject(source[key])) {
      if (!isPlainObject(target[key])) target[key] = {};
      deepMerge(target[key], source[key]);
    } else {
      target[key] = source[key];
    }
  }
  return target;
}

module.exports = { deepMerge };

"use strict";

// Returns one page of items plus paging metadata. Pages are numbered from 1.
function paginate(items, page, pageSize) {
  if (!Number.isInteger(pageSize) || pageSize < 1) throw new RangeError("pageSize must be a positive integer");
  const totalPages = Math.max(1, Math.floor(items.length / pageSize));
  if (!Number.isInteger(page) || page < 1 || page > totalPages) throw new RangeError("page out of range");
  const start = (page - 1) * pageSize;
  return {
    items: items.slice(start, start + pageSize),
    page,
    totalPages,
    hasNext: page < totalPages,
  };
}

module.exports = { paginate };

